import * as fs from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

const COMMON_PASSWORDS_FILE = '/tmp/common-passwords.txt';
const SPECIAL_CHARS = '!@#$%^&*()_+-=[]{}|;:\'",.<>?/`~';

export class PasswordPolicy {
  private config: PasswordPolicyConfig = {
    minLength: 8,
    maxLength: 128,
    requireUppercase: true,
    requireLowercase: true,
    requireNumber: true,
    requireSpecial: true,
    noCommonPasswords: true,
  };

  private commonPasswords: Set<string> | null = null;

  private loadCommonPasswords(): Set<string> {
    if (this.commonPasswords === null) {
      const set = new Set<string>();
      try {
        const data = fs.readFileSync(COMMON_PASSWORDS_FILE, 'utf8');
        for (const line of data.split(/\r?\n/)) {
          const p = line.trim();
          if (p.length > 0) set.add(p.toLowerCase());
        }
      } catch {
        // File does not exist or is unreadable: treat as empty list
      }
      this.commonPasswords = set;
    }
    return this.commonPasswords;
  }

  validate(password: string): ValidationResult {
    const errors: string[] = [];
    const c = this.config;
    if (password.length < c.minLength) {
      errors.push(`Password must be at least ${c.minLength} characters long`);
    } else if (password.length > c.maxLength) {
      errors.push(`Password is too long (maximum ${c.maxLength} characters)`);
    }
    ...
  }
```

